Contract CoCoMESystem::closeStore(storeID:Integer): Boolean {

            precondition:
          store:Store = Store.allInstance()->any(s | s.Name = storeID) and not store.oclIsUndefined() and store.IsOpened = true

            postcondition:
          let store:Store in store.oclIsNew() and Store.allInstance()->includes(store) and store.Name = storeID and store.IsOpened = false and CurrentStore = store and result = true

        }
